package org.codex.nfsugpreview;
import android.app.*;import android.os.*;import java.io.*;import java.nio.*;import java.nio.file.*;import java.security.*;import org.json.*;
public final class MenuCaptureInstrumentation extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 static void ok(boolean b){if(!b)throw new AssertionError();}
 static String hash(byte[] b)throws Exception{byte[] h=MessageDigest.getInstance("SHA-256").digest(b);StringBuilder s=new StringBuilder();for(byte v:h)s.append(String.format("%02x",v&255));return s.toString();}
 public void onStart(){Bundle result=new Bundle();try{File dir=getTargetContext().getFilesDir();String rom=new File(dir,"menu-capture.gba").getPath();byte[] state=Files.readAllBytes(new File(dir,"menu-capture.state").toPath());String[] baseline=new String[90];int snapshots=0,covered=0;byte[] retained=null;String retainedHash=null,lastColor=null;
 for(int pass=0;pass<2;pass++)try(NativeCore core=new NativeCore(rom)){ok(core.loadCheckpoint(state));if(pass==1){ok(NativeMenuCapture.capture(core)==null);ok(!NativeMenuCapture.enable(core,true));ok(core.capture(true)&&core.captureLayers(true)&&NativeMenuCapture.enable(core,true));}
 ByteBuffer pixels=ByteBuffer.allocateDirect(153600);for(int i=0;i<90;i++){ok(core.step(i>=15&&i<17?128:0)==1&&core.frame(pixels));byte[] frame=new byte[153600];pixels.position(0);pixels.get(frame);String digest=hash(frame);if(pass==0){baseline[i]=digest;continue;}ok(baseline[i].equals(digest));byte[] bundle=NativeMenuCapture.capture(core);if(bundle==null)continue;NativeMenuText text=NativeMenuText.fromBundle(bundle);byte[] rgba=new byte[153600];text.rgba().get(rgba);int count=0;for(int k=3;k<rgba.length;k+=4)if(rgba[k]!=0)count++;covered+=count;snapshots++;if(count>0){lastColor=hash(rgba);retained=bundle;retainedHash=hash(bundle);}}
 if(pass==1){ok(core.loadCheckpoint(state)&&NativeMenuCapture.capture(core)==null);final boolean[] rejected={false};Thread t=new Thread(()->{try{NativeMenuCapture.capture(core);}catch(IllegalStateException expected){rejected[0]=true;}});t.start();t.join();ok(rejected[0]);}}
 ok(snapshots==89&&covered==19305&&retained!=null&&hash(retained).equals(retainedHash));ok(lastColor.equals("08b6971595ca6f22314d0a0af979598f57468a1e16b862c12ef8fc1ef4dad5e7"));JSONObject report=new JSONObject();report.put("result","PASS_ANDROID_MENU_CAPTURE_JNI");report.put("original_frames",90);report.put("snapshots",snapshots);report.put("covered_samples",covered);report.put("last_color_sha256",lastColor);report.put("retained_after_close",true);report.put("wrong_thread_rejected",true);report.put("stale_after_load_rejected",true);report.put("gpu",false);try(FileOutputStream out=getTargetContext().openFileOutput("menu-capture-report.json",0)){out.write(report.toString(2).getBytes("UTF-8"));}result.putString("stream",report.toString());finish(Activity.RESULT_OK,result);}catch(Throwable e){android.util.Log.e("NFSUGMenuCapture","Failed",e);result.putString("stream","FAIL: "+e);finish(Activity.RESULT_CANCELED,result);}}
}
